"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[64667],{66460:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>c,frontMatter:()=>a,metadata:()=>d,toc:()=>i});var o=n(31085),h=n(71184);const a={sidebar_position:8,slug:"/bible/Judges/Judges_8",title:"Judges 8",hide_table_of_contents:!0},s="Judges",d={id:"bible/Judges/Judges 8",title:"Judges 8",description:"Chapter 8",source:"@site/docs/bible/Judges/Judges 8.md",sourceDirName:"bible/Judges",slug:"/bible/Judges/Judges_8",permalink:"/docs/bible/Judges/Judges_8",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Judges/Judges 8.md",tags:[],version:"current",sidebarPosition:8,frontMatter:{sidebar_position:8,slug:"/bible/Judges/Judges_8",title:"Judges 8",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Judges 7",permalink:"/docs/bible/Judges/Judges_7"},next:{title:"Judges 9",permalink:"/docs/bible/Judges/Judges_9"}},r={},i=[{value:"Chapter 8",id:"chapter-8",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"judges",children:"Judges"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-8",children:"Chapter 8"}),"\n",(0,o.jsx)(t.p,{children:"Gedeon appeaseth the Ephraimites.  Taketh Zebee and Salmana.  Destroyeth Soccoth and Phanuel.  Refuseth to be king.  Maketh an ephod of the gold of the prey, and dieth in a good old age.  The people return to idolatry."}),"\n",(0,o.jsx)(n,{verse:1,children:"And the men of Ephraim said to him: What is this that thou meanest to do, that thou wouldst not call us, when thou wentest to fight against Madian? And they chid him sharply, and almost offered violence."}),"\n",(0,o.jsx)(n,{verse:2,children:"And he answered them: What could I have done like to that which you have done? Is not one bunch of grapes of Ephraim better than the vintages of Abiezer?"}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: What could I, etc...A meek and humble answer appeased them; who otherwise might have come to extremities. So great is the power of humility both with God and man."})}),"\n",(0,o.jsx)(n,{verse:3,children:"The Lord hath delivered into your hands the princes of Madian, Oreb and Zeb: what could I have done like to what you have done? And when he had said this, their spirit was appeased, with which they swelled against him."}),"\n",(0,o.jsx)(n,{verse:4,children:"And when Gedeon was come to the Jordan, he passed over it with the three hundred men that were with him: who were so weary that they could not pursue after them that fled."}),"\n",(0,o.jsx)(n,{verse:5,children:"And he said to the men of Soccoth: Give, I beseech you, bread to the people that is with me, for they are faint: that we may pursue Zebee, and Salmana, the kings of Madian."}),"\n",(0,o.jsx)(n,{verse:6,children:"The princes of Soccoth answered: Peradventure the palms of the hands of Zebee and Salmana are in thy hand, and therefore thou demandest that we should give bread to thy army."}),"\n",(0,o.jsx)(n,{verse:7,children:"And he said to them: When the Lord therefore shall have delivered Zebee and Salmana into my hands, I will thresh your flesh with the thorns and briers of the desert."}),"\n",(0,o.jsx)(n,{verse:8,children:"And going up from thence, he came to Phanuel: and he spoke the like things to the men of that place. And they also answered him, as the men of Soccoth had answered."}),"\n",(0,o.jsx)(n,{verse:9,children:"He said, therefore, to them also: When I shall return a conqueror in peace, I will destroy this tower."}),"\n",(0,o.jsx)(n,{verse:10,children:"But Zebee and Salmana were resting with all their army. For fifteen thousand men were left of all the troops of the eastern people, and one hundred and twenty thousand warriors that drew the sword were slain."}),"\n",(0,o.jsx)(n,{verse:11,children:"And Gedeon went up by the way of them that dwelt in tents, on the east of Nobe and Jegbaa, and smote the camp of the enemies, who were secure, and suspected no hurt."}),"\n",(0,o.jsx)(n,{verse:12,children:"And Zebee and Salmana fled, and Gedeon pursued and took them, all their host being put in confusion."}),"\n",(0,o.jsx)(n,{verse:13,children:"And returning from the battle before the sun rising,"}),"\n",(0,o.jsx)(n,{verse:14,children:"He took a boy of the men of Soccoth: and he asked him the names of the princes and ancients of Soccoth, and he described unto him seventy-seven men."}),"\n",(0,o.jsx)(n,{verse:15,children:"And he came to Soccoth, and said to them: Behold Zebee, and Salmana, concerning whom you upbraided me, saying: Peradventure the hands of Zebee and Salmana are in thy hands, and therefore thou demandest that we should give bread to the men that are weary and faint."}),"\n",(0,o.jsx)(n,{verse:16,children:"So he took the ancients of the city, and thorns and briers of the desert, and tore them with the same, and cut in pieces the men of Soccoth."}),"\n",(0,o.jsx)(n,{verse:17,children:"And he demolished the tower of Phanuel, and slew the men of the city."}),"\n",(0,o.jsx)(n,{verse:18,children:"And he said to Zebee and Salmana: What manner of men were they, whom you slew in Thabor? They answered: They were like thee, and one of them as the son of a king."}),"\n",(0,o.jsx)(n,{verse:19,children:"He answered them: They were my brethren, the sons of my mother. As the Lord liveth, if you had saved them, I would not kill you."}),"\n",(0,o.jsx)(n,{verse:20,children:"And he said to Jether, his eldest son: Arise, and slay them. But he drew not his sword: for he was afraid, being but yet a boy."}),"\n",(0,o.jsx)(n,{verse:21,children:"And Zebee and Salmana said: Do thou rise and run upon us: because the strength of a man is according to his age: Gedeon rose up, and slew Zebee and Salmana: and he took the ornaments and bosses, with which the necks of the camels of kings are wont to be adorned."}),"\n",(0,o.jsx)(n,{verse:22,children:"And all the men of Israel said to Gedeon: Rule thou over us, and thy son, and thy son's son: because thou hast delivered us from the hand of Madian."}),"\n",(0,o.jsx)(n,{verse:23,children:"And he said to them: I will not rule over you, neither shall my son rule over you, but the Lord shall rule over you."}),"\n",(0,o.jsx)(n,{verse:24,children:"And he said to them: I desire one request of you: Give me the earlets of your spoils. For the Ismaelites were accustomed to wear golden earlets."}),"\n",(0,o.jsx)(n,{verse:25,children:"They answered: We will give them most willingly. And spreading a mantle on the ground, they cast upon it the earlets of the spoils."}),"\n",(0,o.jsx)(n,{verse:26,children:"And the weight of the earlets that he requested, was a thousand seven hundred sicles of gold, besides the ornaments, and jewels, and purple raiment, which the kings of Madian were wont to use, and besides the golden chains that were about the camels necks."}),"\n",(0,o.jsx)(n,{verse:27,children:"And Gedeon made an ephod thereof, and put it in his city Ephra. And all Israel committed fornication with it, and it became a ruin to Gedeon, and to all his house."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: An ephod...A priestly garment which Gedeon made with a good design; but the Israelites, after his death, abused it by making it an instrument of their idolatrous worship."})}),"\n",(0,o.jsx)(n,{verse:28,children:"But Madian was humbled before the children of Israel, neither could they any more lift up their heads: but the land rested for forty years, while Gedeon presided."}),"\n",(0,o.jsx)(n,{verse:29,children:"So Jerobaal, the son of Joas, went and dwelt in his own house:"}),"\n",(0,o.jsx)(n,{verse:30,children:"And he had seventy sons, who came out of his thigh, for he had many wives."}),"\n",(0,o.jsx)(n,{verse:31,children:"And his concubine, that he had in Sichem, bore him a son, whose name was Abimelech."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: His concubine...She was his servant, but not his harlot: and is called his concubine, as wives of an inferior degree are commonly called in the Old Testament, though otherwise lawfully married."})}),"\n",(0,o.jsx)(n,{verse:32,children:"And Gedeon, the son of Joas died in a good old age, and was buried in the sepulchre of his father, in Ephra, of the family of Ezri."}),"\n",(0,o.jsx)(n,{verse:33,children:"But after Gedeon was dead, the children of Israel turned again, and committed fornication with Baalim. And they made a covenant with Baal, that he should be their god:"}),"\n",(0,o.jsx)(n,{verse:34,children:"And they remembered not the Lord their God, who delivered them out of the hands of all their enemies round about:"}),"\n",(0,o.jsx)(n,{verse:35,children:"Neither did they shew mercy to the house of Jerobaal Gedeon, according to all the good things he had done to Israel."})]})}function c(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>d});var o=n(14041);const h={},a=o.createContext(h);function s(e){const t=o.useContext(a);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function d(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:s(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);